package server

import (
	"encoding/json"
	"errors"
	"io/fs"
	"net/http"
	"os"
	"path/filepath"
)

// handleAgentBoard serves the read-only board snapshot produced outside
// cc-webui. The UI must not depend on an iCafe login: a local JSON file is the
// only contract, so external users can see the board with the cc-webui token
// alone. The file is generated by work/tools/agent_board_snapshot.py from the
// iCafe cache plus the local routing table.
func (s *Server) handleAgentBoard(w http.ResponseWriter, r *http.Request) {
	path := s.cfg().AgentBoardPath
	if path == "" {
		path = filepath.Join(s.cfg().DataDir, "agent-board.json")
	}
	data, err := os.ReadFile(path)
	if errors.Is(err, fs.ErrNotExist) {
		writeJSON(w, http.StatusOK, map[string]any{
			"generated_at": "",
			"source":       "missing",
			"tasks":        []any{},
			"projects":     []any{},
			"counts":       map[string]int{},
			"error":        "看板快照不存在：" + path,
		})
		return
	}
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "读取看板快照失败: "+err.Error())
		return
	}
	// Validate before serving: a truncated snapshot should surface as an error
	// in the board, not as a JSON parse failure in the browser.
	var payload any
	if err := json.Unmarshal(data, &payload); err != nil {
		writeErr(w, http.StatusInternalServerError, "看板快照 JSON 无效: "+err.Error())
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(data)
}
